/* Generated by vite.config.ts. Cache only immutable app/runtime resources. */
const CACHE_NAME = `vto-example-__VTO_CACHE_VERSION__`;
const PRECACHE_URLS = __VTO_PRECACHE_URLS__;
const PRECACHE_SET = new Set(PRECACHE_URLS.map((path) => new URL(path, self.location.origin).href));
const MEDIAPIPE_WASM = /^https:\/\/cdn\.jsdelivr\.net\/npm\/@mediapipe\/tasks-vision@0\.10\.22-rc\.20250304\/wasm\/vision_wasm_(?:nosimd_)?internal\.(?:js|wasm)$/;
const FACE_MODEL = 'https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task';

function isApproved(request) {
  if (request.method !== 'GET') return false;
  const url = new URL(request.url);
  if (url.search || url.hash) return false;
  if (url.origin === self.location.origin) return PRECACHE_SET.has(url.href) || /^\/assets\/[A-Za-z0-9_.-]+\.(?:js|css)$/.test(url.pathname);
  return MEDIAPIPE_WASM.test(url.href) || url.href === FACE_MODEL;
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    await cache.addAll(PRECACHE_URLS);
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    const appCaches = names.filter((name) => name.startsWith('vto-example-'));
    // Keep the previous shell for tabs that were opened just before this worker claimed them.
    await Promise.all(appCaches.slice(0, -2).map((name) => caches.delete(name)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (!isApproved(request)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    // Precache requests and module/WASM runtime requests can use different fetch modes/headers.
    const cached = await cache.match(request, { ignoreVary: true });
    if (cached) return cached;
    const oldShell = (await caches.keys()).filter((name) => name.startsWith('vto-example-') && name !== CACHE_NAME).reverse();
    for (const name of oldShell) {
      const previous = await caches.open(name).then((previousCache) => previousCache.match(request, { ignoreVary: true }));
      if (previous) return previous;
    }
    try {
      const response = await fetch(request);
      const url = new URL(request.url);
      const acceptableType = response.type === 'basic' || response.type === 'cors' || (url.origin === self.location.origin && response.type === 'default');
      if (response.ok && acceptableType) await cache.put(request, response.clone());
      return response;
    } catch (error) {
      const fallback = request.mode === 'navigate' ? await cache.match(new URL('/index.html', self.location.origin).href) : undefined;
      if (fallback) return fallback;
      throw error;
    }
  })());
});
